interface Calculator {
    void add(int a, int b);
}

class Calculator1 { void add(int a, int b) { } }
class Calculator2 { void sum(int a, int b) { } }
class Calculator3 { void addition(int a, int b) { } }

interface Calculator {
    void add(int a, int b);
}
class Calculator1 implements Calculator {
    public void add(int a, int b) {
        System.out.println("Calculator1 sum: " + (a + b));
    }
}
class Calculator2 implements Calculator {
    public void add(int a, int b) {
        System.out.println("Calculator2 sum: " + (a + b));
    }
}
class Calculator3 implements Calculator {
    public void add(int a, int b) {
        System.out.println("Calculator3 sum: " + (a + b));
    }
}
public class Main {
    public static void main(String[] args) {
        Calculator c1 = new Calculator1();
        Calculator c2 = new Calculator2();
        Calculator c3 = new Calculator3();
        c1.add(10, 20);
        c2.add(10, 20);
        c3.add(10, 20);
    }
}

interface Calculator {
    void add(int a, int b);                       // same as the line below
    public abstract void sub(int a, int b);
}

interface Calculator {
    void add(int a, int b);
}
class Calculator1 implements Calculator {
    void add(int a, int b) { }     // compilation error
}

interface Calculator {
    void add(int a, int b);
}
class Calculator1 implements Calculator {
    public void add(int a, int b) { }
    void subtract(int a, int b) { }       // specialized method
}
public class Main {
    public static void main(String[] args) {
        Calculator c = new Calculator1();
        c.subtract(10, 5);                // compilation error
    }
}

interface Calculator {
    void add(int a, int b);
}
class Calculator1 implements Calculator {
    public void add(int a, int b) {
        System.out.println("Sum: " + (a + b));
    }
    void subtract(int a, int b) {
        System.out.println("Difference: " + (a - b));
    }
}
public class Main {
    public static void main(String[] args) {
        Calculator c = new Calculator1();   // upcasting
        c.add(10, 5);
        ((Calculator1) c).subtract(10, 5);  // downcasting
    }
}

interface Calculator {
    void add(int a, int b);
    void subtract(int a, int b);
}
class Calculator1 implements Calculator {
    public void add(int a, int b) { }     // subtract() is missing
}

abstract class Calculator1 implements Calculator {
    public void add(int a, int b) {
        System.out.println("Sum: " + (a + b));
    }
}
class Calculator2 extends Calculator1 {
    public void subtract(int a, int b) {
        System.out.println("Difference: " + (a - b));
    }
}

interface Calculator {
    void add(int a, int b);
}
class Demo {
    void multiply(int a, int b) {
        System.out.println("Product: " + (a * b));
    }
}
class Calculator1 extends Demo implements Calculator {
    public void add(int a, int b) {
        System.out.println("Sum: " + (a + b));
    }
}
public class Main {
    public static void main(String[] args) {
        Calculator1 c = new Calculator1();
        c.add(2, 3);
        c.multiply(2, 3);
    }
}

